import { rgbaToCss } from '../../parser/kmlColor.ts';
import type {
  Geometry,
  KmlDocument,
  PlacemarkNode,
  Position,
  ResolvedStyle,
  Rgba,
} from '../../model/types.ts';
import { visitAll } from '../../model/traverse.ts';
import { MAX_RENDER_COORDINATES } from '../../model/statistics.ts';

/** Feature property bag carried on every GeoJSON feature. */
export interface FeatureProps {
  featureId: string;
  renderId: number;
  title: string;
  // Data-driven paint inputs (pre-computed CSS strings / numbers).
  pointColor: string;
  lineColor: string;
  lineWidth: number;
  fillColor: string;
  fillOpacity: number;
  outlineColor: string;
  outlineWidth: number;
  outlineOpacity: number;
  hoverLineColor: string;
  hoverLineWidth: number;
  hoverFillColor: string;
  hoverFillOpacity: number;
  hoverOutlineColor: string;
  hoverOutlineWidth: number;
  hoverOutlineOpacity: number;
  // Icon inputs — `iconHref` is the resolved image URL ('' when none). The
  // renderer registers images and fills in `iconId` (the map's image name).
  iconHref: string;
  iconScale: number;
  iconRotate: number;
  iconId: string;
  labelColor: string;
  labelSize: number;
  [key: string]: string | number;
}

export interface DocumentGeoJSON {
  points: GeoJSON.FeatureCollection<GeoJSON.Point, FeatureProps>;
  lines: GeoJSON.FeatureCollection<GeoJSON.LineString, FeatureProps>;
  polygons: GeoJSON.FeatureCollection<GeoJSON.Polygon, FeatureProps>;
}

const DEFAULT_POINT: Rgba = { r: 255, g: 87, b: 34, a: 1 };
const DEFAULT_LINE: Rgba = { r: 66, g: 133, b: 244, a: 1 };
const DEFAULT_FILL: Rgba = { r: 66, g: 133, b: 244, a: 0.35 };

/** Convert the document's placemarks into GeoJSON grouped by geometry type. */
export function documentToGeoJSON(doc: KmlDocument): DocumentGeoJSON {
  const points: GeoJSON.Feature<GeoJSON.Point, FeatureProps>[] = [];
  const lines: GeoJSON.Feature<GeoJSON.LineString, FeatureProps>[] = [];
  const polygons: GeoJSON.Feature<GeoJSON.Polygon, FeatureProps>[] = [];

  const stride = doc.statistics && doc.statistics.coordinateCount > MAX_RENDER_COORDINATES
    ? Math.ceil(doc.statistics.coordinateCount / MAX_RENDER_COORDINATES)
    : 1;
  let renderId = 1;
  visitAll(doc, (node) => {
    if (node.kind !== 'placemark') return;
    emitGeometry(node, node.geometry, { points, lines, polygons }, stride, renderId++);
  });

  return {
    points: fc(points),
    lines: fc(lines),
    polygons: fc(polygons),
  };
}

interface Buckets {
  points: GeoJSON.Feature<GeoJSON.Point, FeatureProps>[];
  lines: GeoJSON.Feature<GeoJSON.LineString, FeatureProps>[];
  polygons: GeoJSON.Feature<GeoJSON.Polygon, FeatureProps>[];
}

function emitGeometry(node: PlacemarkNode, geom: Geometry, buckets: Buckets, stride: number, renderId: number): void {
  const props = featureProps(node, renderId);
  switch (geom.type) {
    case 'Point':
      buckets.points.push(feature('Point', to2D(geom.coordinates), props));
      break;
    case 'LineString':
      buckets.lines.push(feature('LineString', decimate(geom.coordinates, stride, false).map(to2D), props));
      break;
    case 'Polygon':
      buckets.polygons.push(feature('Polygon', geom.coordinates.map((ring) => decimate(ring, stride, true).map(to2D)), props));
      break;
    case 'MultiGeometry':
      for (const g of geom.geometries) emitGeometry(node, g, buckets, stride, renderId);
      break;
  }
}

function to2D(position: Position): [number, number] {
  return [position[0], position[1]];
}

function decimate(coordinates: Position[], stride: number, closed: boolean): Position[] {
  if (stride <= 1 || coordinates.length <= (closed ? 4 : 2)) return coordinates;
  const last = coordinates[coordinates.length - 1]!;
  const result: Position[] = [coordinates[0]!];
  for (let index = stride; index < coordinates.length - 1; index += stride) {
    result.push(coordinates[index]!);
  }
  if (result[result.length - 1] !== last) result.push(last);
  if (closed && result.length < 4) return coordinates.slice(0, 4);
  return result;
}

function featureProps(node: PlacemarkNode, renderId: number): FeatureProps {
  const s: ResolvedStyle = node.style;
  const hover: ResolvedStyle = node.highlightStyle ?? s;
  const normal = paintProps(s);
  const highlight = paintProps(hover);
  return {
    featureId: node.id,
    renderId,
    title: node.name ?? '',
    pointColor: rgbaToCss(s.icon?.color ?? DEFAULT_POINT),
    ...normal,
    hoverLineColor: highlight.lineColor,
    hoverLineWidth: highlight.lineWidth,
    hoverFillColor: highlight.fillColor,
    hoverFillOpacity: highlight.fillOpacity,
    hoverOutlineColor: highlight.outlineColor,
    hoverOutlineWidth: highlight.outlineWidth,
    hoverOutlineOpacity: highlight.outlineOpacity,
    iconHref: s.icon?.href ?? '',
    iconScale: s.icon?.scale ?? 1,
    iconRotate: s.icon?.heading ?? 0,
    iconId: '', // filled in by the icon manager once images are registered
    labelColor: rgbaToCss(s.label?.color ?? { r: 255, g: 255, b: 255, a: 1 }),
    labelSize: Math.max(8, 12 * (s.label?.scale ?? 1)),
  };
}

function paintProps(s: ResolvedStyle): Pick<
  FeatureProps,
  'lineColor' | 'lineWidth' | 'fillColor' | 'fillOpacity' | 'outlineColor' | 'outlineWidth' | 'outlineOpacity'
> {
  const fill = s.poly?.fill ? s.poly.color : DEFAULT_FILL;
  const outline = s.poly?.outline === false ? 0 : 1;
  return {
    lineColor: rgbaToCss(s.line?.color ?? DEFAULT_LINE),
    lineWidth: s.line?.width ?? 2,
    fillColor: rgbaToCss({ ...fill, a: 1 }),
    fillOpacity: s.poly ? (s.poly.fill ? s.poly.color.a : 0) : DEFAULT_FILL.a,
    outlineColor: rgbaToCss(s.line?.color ?? s.poly?.color ?? DEFAULT_LINE),
    outlineWidth: s.line?.width ?? 1.5,
    outlineOpacity: outline,
  };
}

function feature<T extends GeoJSON.Geometry>(
  type: T['type'],
  coordinates: Position | Position[] | Position[][],
  props: FeatureProps,
): GeoJSON.Feature<T, FeatureProps> {
  return {
    type: 'Feature',
    id: props.renderId,
    geometry: { type, coordinates } as unknown as T,
    properties: props,
  };
}

function fc<T extends GeoJSON.Geometry>(
  features: GeoJSON.Feature<T, FeatureProps>[],
): GeoJSON.FeatureCollection<T, FeatureProps> {
  return { type: 'FeatureCollection', features };
}
