import type { Geometry, Position } from '../model/types.ts';
import { parseCoordinates } from './parseCoordinates.ts';
import { childElement, childElements, childText, localName } from './xml.ts';

const GEOMETRY_NAMES = new Set([
  'Point',
  'LineString',
  'LinearRing',
  'Polygon',
  'MultiGeometry',
]);

/**
 * Parse the geometry contained directly in a Placemark (or MultiGeometry).
 * Returns undefined if no supported geometry is present.
 */
export function parsePlacemarkGeometry(placemark: Element): Geometry | undefined {
  for (let child = placemark.firstElementChild; child; child = child.nextElementSibling) {
    if (GEOMETRY_NAMES.has(localName(child))) {
      const g = parseGeometryElement(child);
      if (g) return g;
    }
  }
  return undefined;
}

function parseGeometryElement(el: Element): Geometry | undefined {
  switch (localName(el)) {
    case 'Point': {
      const coords = parseCoordinates(childText(el, 'coordinates'));
      const first = coords[0];
      return first ? { type: 'Point', coordinates: first } : undefined;
    }
    case 'LineString': {
      const coordinates = parseCoordinates(childText(el, 'coordinates'));
      return coordinates.length >= 2 ? { type: 'LineString', coordinates } : undefined;
    }
    case 'LinearRing': {
      const coordinates = parseCoordinates(childText(el, 'coordinates'));
      // A bare LinearRing is rendered as a closed line.
      return coordinates.length >= 2 ? { type: 'LineString', coordinates } : undefined;
    }
    case 'Polygon':
      return parsePolygon(el);
    case 'MultiGeometry': {
      const geometries: Geometry[] = [];
      for (let child = el.firstElementChild; child; child = child.nextElementSibling) {
        if (GEOMETRY_NAMES.has(localName(child))) {
          const g = parseGeometryElement(child);
          if (g) geometries.push(g);
        }
      }
      if (geometries.length === 0) return undefined;
      return { type: 'MultiGeometry', geometries };
    }
    default:
      return undefined;
  }
}

function parsePolygon(el: Element): Geometry | undefined {
  const rings: Position[][] = [];

  const outer = childElement(el, 'outerBoundaryIs');
  if (outer) {
    const ring = ringCoords(outer);
    if (ring) rings.push(ring);
  }
  for (const inner of childElements(el, 'innerBoundaryIs')) {
    const ring = ringCoords(inner);
    if (ring) rings.push(ring);
  }

  if (rings.length === 0 || !rings[0]) return undefined;
  return { type: 'Polygon', coordinates: rings };
}

function ringCoords(boundary: Element): Position[] | undefined {
  const linearRing = childElement(boundary, 'LinearRing');
  if (!linearRing) return undefined;
  const coords = parseCoordinates(childText(linearRing, 'coordinates'));
  if (coords.length < 3) return undefined;
  // Ensure the ring is explicitly closed (GeoJSON convention).
  const first = coords[0];
  const last = coords[coords.length - 1];
  if (first && last && (first[0] !== last[0] || first[1] !== last[1])) {
    coords.push(first);
  }
  return coords;
}
