import type { Position } from '../model/types.ts';

/**
 * Parse a KML <coordinates> string into a list of positions.
 *
 * KML coordinates are whitespace-separated tuples, each `lon,lat[,alt]`.
 * Real-world files are messy: arbitrary whitespace/newlines between tuples,
 * trailing commas, and stray empty tokens. We parse defensively and drop any
 * tuple that does not yield finite lon/lat.
 */
export function parseCoordinates(text: string | null | undefined): Position[] {
  if (!text) return [];
  const out: Position[] = [];
  // Split on any whitespace run; each token is one tuple.
  for (const token of text.trim().split(/\s+/)) {
    if (!token) continue;
    const parts = token.split(',');
    if (parts.length < 2) continue;
    // Guard empty fields: Number('') is 0, which would silently pass.
    if (parts[0] === '' || parts[1] === '') continue;
    const lon = Number(parts[0]);
    const lat = Number(parts[1]);
    if (!Number.isFinite(lon) || !Number.isFinite(lat)) continue;
    if (parts.length >= 3 && parts[2] !== '' && Number.isFinite(Number(parts[2]))) {
      out.push([lon, lat, Number(parts[2])]);
    } else {
      out.push([lon, lat]);
    }
  }
  return out;
}
