import { unzip } from 'fflate';

/** Archive limits protect the main process from zip bombs and accidental dumps. */
export const MAX_ARCHIVE_ENTRIES = 10_000;
export const MAX_UNCOMPRESSED_BYTES = 500 * 1024 * 1024;

export interface UnzippedArchive {
  /** Archive path (normalized, forward slashes) → file bytes. */
  entries: Map<string, Uint8Array>;
  /** Path of the root KML document within the archive. */
  rootKmlPath: string;
  /** Decoded text of the root KML document. */
  rootKml: string;
}

/**
 * Unzip a KMZ archive and locate its root KML document.
 *
 * Per the KMZ spec the main document is the first `.kml` at the archive root
 * (conventionally `doc.kml`). We prefer a root-level `.kml`, falling back to
 * the shallowest `.kml` anywhere in the archive.
 */
export async function unzipKmz(data: Uint8Array): Promise<UnzippedArchive> {
  const raw = await new Promise<Record<string, Uint8Array>>((resolve, reject) => {
    unzip(data, (err, files) => (err ? reject(err) : resolve(files)));
  });

  const entries = new Map<string, Uint8Array>();
  let totalBytes = 0;
  for (const [name, bytes] of Object.entries(raw)) {
    // Skip directory entries (zero-length, trailing slash).
    if (name.endsWith('/')) continue;
    if (entries.size >= MAX_ARCHIVE_ENTRIES) {
      throw new Error(`KMZ has more than ${MAX_ARCHIVE_ENTRIES.toLocaleString()} files.`);
    }
    totalBytes += bytes.byteLength;
    if (totalBytes > MAX_UNCOMPRESSED_BYTES) {
      throw new Error(`KMZ expands beyond the ${MAX_UNCOMPRESSED_BYTES / 1024 / 1024} MB safety limit.`);
    }
    entries.set(normalizePath(name), bytes);
  }

  const rootKmlPath = pickRootKml(entries);
  if (!rootKmlPath) {
    throw new Error('KMZ archive contains no .kml document.');
  }
  const rootBytes = entries.get(rootKmlPath)!;
  const rootKml = new TextDecoder('utf-8').decode(rootBytes);

  return { entries, rootKmlPath, rootKml };
}

function pickRootKml(entries: Map<string, Uint8Array>): string | undefined {
  const kmls = [...entries.keys()].filter((p) => p.toLowerCase().endsWith('.kml'));
  if (kmls.length === 0) return undefined;

  // Prefer a root-level doc.kml, then any root-level .kml, then shallowest.
  const rootLevel = kmls.filter((p) => !p.includes('/'));
  const docKml = rootLevel.find((p) => p.toLowerCase() === 'doc.kml');
  if (docKml) return docKml;
  if (rootLevel.length > 0) return rootLevel.sort()[0];

  return kmls.sort((a, b) => depth(a) - depth(b) || a.localeCompare(b))[0];
}

function depth(path: string): number {
  return path.split('/').length;
}

/** Normalize to forward slashes and strip any leading `./`. */
export function normalizePath(path: string): string {
  return path.replace(/\\/g, '/').replace(/^\.\//, '');
}
