import type {
  BalloonStyle,
  HotspotUnit,
  IconStyle,
  LabelStyle,
  LineStyle,
  PolyStyle,
  ResolvedStyle,
} from '../model/types.ts';
import { parseKmlColor, WHITE } from './kmlColor.ts';
import { childElement, childNumber, childRawText, childText } from './xml.ts';

/**
 * A function that turns a KML href (possibly a relative path into a KMZ
 * archive) into a usable URL. Injected so the parser stays independent of the
 * loader/blob-URL machinery.
 */
export type HrefResolver = (href: string) => string;

/** Parse a single <Style> element into a ResolvedStyle. */
export function parseStyleElement(styleEl: Element, resolveHref: HrefResolver): ResolvedStyle {
  const style: ResolvedStyle = {};

  const iconStyle = childElement(styleEl, 'IconStyle');
  if (iconStyle) style.icon = parseIconStyle(iconStyle, resolveHref);

  const lineStyle = childElement(styleEl, 'LineStyle');
  if (lineStyle) style.line = parseLineStyle(lineStyle);

  const polyStyle = childElement(styleEl, 'PolyStyle');
  if (polyStyle) style.poly = parsePolyStyle(polyStyle);

  const labelStyle = childElement(styleEl, 'LabelStyle');
  if (labelStyle) style.label = parseLabelStyle(labelStyle);

  const balloonStyle = childElement(styleEl, 'BalloonStyle');
  if (balloonStyle) style.balloon = parseBalloonStyle(balloonStyle);

  return style;
}

function parseIconStyle(el: Element, resolveHref: HrefResolver): IconStyle {
  const icon = childElement(el, 'Icon');
  const rawHref = icon ? childText(icon, 'href') : undefined;
  const hotSpot = childElement(el, 'hotSpot');

  return {
    href: rawHref ? resolveHref(rawHref) : undefined,
    scale: childNumber(el, 'scale') ?? 1,
    color: parseKmlColor(childText(el, 'color')) ?? WHITE,
    heading: childNumber(el, 'heading'),
    hotspot: hotSpot
      ? {
          x: Number(hotSpot.getAttribute('x') ?? 0),
          y: Number(hotSpot.getAttribute('y') ?? 0),
          xUnits: (hotSpot.getAttribute('xunits') as HotspotUnit) ?? unit(hotSpot, 'xunits'),
          yUnits: (hotSpot.getAttribute('yunits') as HotspotUnit) ?? unit(hotSpot, 'yunits'),
        }
      : undefined,
  };
}

// Attribute names are case-sensitive in XML; KML uses xunits/yunits.
function unit(el: Element, attr: string): HotspotUnit {
  const v = el.getAttribute(attr) ?? el.getAttribute(attr.replace('units', 'Units'));
  return (v as HotspotUnit) ?? 'fraction';
}

function parseLineStyle(el: Element): LineStyle {
  return {
    color: parseKmlColor(childText(el, 'color')) ?? WHITE,
    width: childNumber(el, 'width') ?? 1,
  };
}

function parsePolyStyle(el: Element): PolyStyle {
  const fill = childText(el, 'fill');
  const outline = childText(el, 'outline');
  return {
    color: parseKmlColor(childText(el, 'color')) ?? WHITE,
    fill: fill == null ? true : fill === '1' || fill.toLowerCase() === 'true',
    outline: outline == null ? true : outline === '1' || outline.toLowerCase() === 'true',
  };
}

function parseLabelStyle(el: Element): LabelStyle {
  return {
    color: parseKmlColor(childText(el, 'color')) ?? WHITE,
    scale: childNumber(el, 'scale') ?? 1,
  };
}

function parseBalloonStyle(el: Element): BalloonStyle {
  return {
    text: childRawText(el, 'text'),
    bgColor: parseKmlColor(childText(el, 'bgColor')),
    textColor: parseKmlColor(childText(el, 'textColor')),
  };
}

/** Merge two resolved styles; `override` wins per-category when present. */
export function mergeStyles(base: ResolvedStyle, override: ResolvedStyle): ResolvedStyle {
  return {
    icon: override.icon ?? base.icon,
    line: override.line ?? base.line,
    poly: override.poly ?? base.poly,
    label: override.label ?? base.label,
    balloon: override.balloon ?? base.balloon,
  };
}
