import type { BBox, KmlDocument, KmlNode, Warning, WarningKind } from '../model/types.ts';
import type { HrefResolver } from './parseStyle.ts';
import { newBounds, parseChildren, type ParseContext } from './parseFeature.ts';
import { buildStyleTable } from './resolveStyles.ts';
import { parseStreamingXml } from './streamingXml.ts';

/** Href resolver used for plain .kml (no archive): pass hrefs through as-is. */
export const identityResolver: HrefResolver = (href) => href;

export interface ParseOptions {
  /** Resolve KML hrefs (relative archive paths) to usable URLs. */
  resolveHref?: HrefResolver;
}

/**
 * Parse a KML string into the engine-agnostic document model.
 * Throws on XML that cannot be parsed at all; otherwise returns a document
 * (possibly empty) with any unsupported constructs recorded in `warnings`.
 */
export function parseKml(kml: string, options: ParseOptions = {}): KmlDocument {
  const dom = new DOMParser().parseFromString(kml, 'application/xml');
  const parserError = dom.querySelector('parsererror');
  if (parserError) {
    throw new Error(`Invalid KML/XML: ${parserError.textContent?.trim() ?? 'parse error'}`);
  }

  const kmlEl = findKmlRoot(dom);
  if (!kmlEl) {
    throw new Error('No <kml> root element found.');
  }

  return parseKmlElement(kmlEl, options);
}

/** Worker-safe parser backed by a strict, namespace-aware SAX tokenizer. */
export function parseKmlStreaming(kml: string, options: ParseOptions = {}): KmlDocument {
  return parseKmlElement(parseStreamingXml(kml), options);
}

function parseKmlElement(kmlEl: Element, options: ParseOptions): KmlDocument {
  const resolveHref = options.resolveHref ?? identityResolver;
  const styleTable = buildStyleTable(kmlEl, resolveHref);

  const warnings = new Map<WarningKind, Warning>();
  const ctx: ParseContext = {
    styleTable,
    resolveHref,
    nodeIndex: new Map<string, KmlNode>(),
    warnings,
    bounds: newBounds(),
    seq: { n: 0 },
  };

  const roots = parseChildren(kmlEl, ctx);

  let bounds: BBox | undefined;
  if (ctx.bounds.any) {
    bounds = [ctx.bounds.west, ctx.bounds.south, ctx.bounds.east, ctx.bounds.north];
  }

  return {
    roots,
    nodeIndex: ctx.nodeIndex,
    bounds,
    warnings: [...warnings.values()],
  };
}

/**
 * Locate the container element whose children are the top-level features.
 * For the normal `<kml>` root that is `<kml>` itself. If a document omits the
 * `<kml>` wrapper and starts at `<Document>`/`<Folder>`, we return that element
 * so its children are parsed directly (the wrapper node is elided).
 */
function findKmlRoot(dom: Document): Element | null {
  return dom.documentElement ?? null;
}
