/**
 * The intermediate document model — the contract that decouples KML parsing
 * from rendering. Nothing in this file may reference a map engine.
 *
 * Design goals:
 *  - Preserve the full KML tree (Document/Folder/Placemark hierarchy) that a
 *    plain KML→GeoJSON conversion throws away.
 *  - Keep geometry engine-neutral, in GeoJSON axis order: [lon, lat, alt?].
 *  - Store fully-resolved styles inline so a renderer never re-walks style
 *    tables (StyleMap is already collapsed into `style` + `highlightStyle`).
 */

/** A coordinate in GeoJSON axis order. Altitude is optional. */
export type Position = [number, number] | [number, number, number];

/** Bounding box as [west, south, east, north]. */
export type BBox = [number, number, number, number];

/** Untrusted HTML (e.g. placemark descriptions). MUST be sanitized before it
 * ever reaches the DOM. Branded as an alias to make that obligation visible. */
export type RawHtml = string;

/** RGBA colour. Channels are 0–255; alpha is 0–1. */
export interface Rgba {
  r: number;
  g: number;
  b: number;
  a: number;
}

// ---------------------------------------------------------------------------
// Geometry
// ---------------------------------------------------------------------------

export type Geometry =
  | { type: 'Point'; coordinates: Position }
  | { type: 'LineString'; coordinates: Position[] }
  | { type: 'Polygon'; coordinates: Position[][] } // [outerRing, ...innerRings]
  | { type: 'MultiGeometry'; geometries: Geometry[] };

// ---------------------------------------------------------------------------
// Styles (fully resolved — StyleMap already collapsed)
// ---------------------------------------------------------------------------

export type HotspotUnit = 'fraction' | 'pixels' | 'insetPixels';

export interface IconStyle {
  href?: string; // resolved URL (blob: for KMZ assets), may be empty for default
  scale: number;
  color: Rgba;
  heading?: number;
  hotspot?: { x: number; y: number; xUnits: HotspotUnit; yUnits: HotspotUnit };
}

export interface LineStyle {
  color: Rgba;
  width: number;
}

export interface PolyStyle {
  color: Rgba;
  fill: boolean;
  outline: boolean;
}

export interface LabelStyle {
  color: Rgba;
  scale: number;
}

export interface BalloonStyle {
  text?: RawHtml;
  bgColor?: Rgba;
  textColor?: Rgba;
}

export interface ResolvedStyle {
  icon?: IconStyle;
  line?: LineStyle;
  poly?: PolyStyle;
  label?: LabelStyle;
  balloon?: BalloonStyle;
}

// ---------------------------------------------------------------------------
// Tree nodes
// ---------------------------------------------------------------------------

export interface NodeBase {
  /** Stable id — generated if the KML element has no id attribute. */
  id: string;
  name?: string;
  /** Untrusted description HTML — sanitize at render time only. */
  description?: RawHtml;
  /** From <visibility>; defaults to true. */
  visibility: boolean;
  /** Folder/Document expanded state from <open>. */
  open?: boolean;
  snippet?: string;
}

export interface DocumentNode extends NodeBase {
  kind: 'document';
  children: KmlNode[];
}

export interface FolderNode extends NodeBase {
  kind: 'folder';
  children: KmlNode[];
}

export interface PlacemarkNode extends NodeBase {
  kind: 'placemark';
  geometry: Geometry;
  style: ResolvedStyle;
  /** Highlight state from a StyleMap, if present. */
  highlightStyle?: ResolvedStyle;
  extendedData?: Record<string, string>;
}

export interface GroundOverlayNode extends NodeBase {
  kind: 'groundOverlay';
  /** Resolved image URL (blob: for KMZ assets). */
  iconHref: string;
  latLonBox: {
    north: number;
    south: number;
    east: number;
    west: number;
    rotation: number;
  };
  drawOrder?: number;
  /** <color> tint / opacity. */
  color?: Rgba;
}

/** A viewport-anchored KML overlay, commonly used as a map legend. */
export interface ScreenOverlayNode extends NodeBase {
  kind: 'screenOverlay';
  /** Resolved image URL (blob: for KMZ assets). */
  iconHref: string;
  /** Position of the overlay's anchor in the viewport. */
  screenXY: { x: number; y: number; xUnits: HotspotUnit; yUnits: HotspotUnit };
  /** Position inside the image that is attached to screenXY. */
  overlayXY: { x: number; y: number; xUnits: HotspotUnit; yUnits: HotspotUnit };
  drawOrder?: number;
}

export type KmlNode = DocumentNode | FolderNode | PlacemarkNode | GroundOverlayNode | ScreenOverlayNode;

/** A node that has renderable children (Document or Folder). */
export type ContainerNode = DocumentNode | FolderNode;

export function isContainer(node: KmlNode): node is ContainerNode {
  return node.kind === 'document' || node.kind === 'folder';
}

// ---------------------------------------------------------------------------
// Warnings for unsupported constructs
// ---------------------------------------------------------------------------

export type WarningKind =
  | 'NetworkLink'
  | 'Model'
  | 'ScreenOverlay'
  | 'PhotoOverlay'
  | 'Tour'
  | 'Track'
  | 'TimePrimitive'
  | 'ParseError';

/** How the viewer handled a KML construct it cannot reproduce exactly. */
export type CompatibilityDisposition = 'approximated' | 'skipped';

export interface Warning {
  kind: WarningKind;
  message: string;
  count: number;
  disposition: CompatibilityDisposition;
}

// ---------------------------------------------------------------------------
// Document
// ---------------------------------------------------------------------------

export interface KmlDocument {
  /** Top-level children of <kml>. */
  roots: KmlNode[];
  /** id → node, for O(1) tree operations. */
  nodeIndex: Map<string, KmlNode>;
  /** Overall bounds [w, s, e, n] for the initial fitBounds, if any geometry. */
  bounds?: BBox;
  /** Unsupported constructs encountered, aggregated by kind. */
  warnings: Warning[];
  /** Load and geometry metrics used for large-document safeguards and UX. */
  statistics?: DocumentStatistics;
}

export interface GeometryCounts {
  points: number;
  lines: number;
  polygons: number;
  overlays: number;
}

export interface DocumentStatistics {
  featureCount: number;
  coordinateCount: number;
  geometry: GeometryCounts;
  sourceBytes: number;
  expandedBytes: number;
  parseDurationMs: number;
  simplified: boolean;
}
