import type { ResolvedStyle } from '../model/types.ts';
import { mergeStyles, parseStyleElement, type HrefResolver } from './parseStyle.ts';
import { childElements, childText, localName } from './xml.ts';

/**
 * A style table maps shared style ids (as referenced by `#id`) to either a
 * single resolved style (from <Style>) or a normal/highlight pair (from
 * <StyleMap>).
 */
export interface StyleTableEntry {
  normal: ResolvedStyle;
  highlight?: ResolvedStyle;
}

export type StyleTable = Map<string, StyleTableEntry>;

/**
 * Scan the whole KML tree for <Style id> and <StyleMap id> and build a lookup
 * table. Two passes: first every <Style>, then every <StyleMap> (which may
 * reference the styles collected in pass one).
 */
export function buildStyleTable(root: Element, resolveHref: HrefResolver): StyleTable {
  const table: StyleTable = new Map();

  const styleEls: Element[] = [];
  const styleMapEls: Element[] = [];
  collect(root, styleEls, styleMapEls);

  // Pass 1: plain styles.
  for (const el of styleEls) {
    const id = el.getAttribute('id');
    if (id) table.set(id, { normal: parseStyleElement(el, resolveHref) });
  }

  // Pass 2: style maps (normal/highlight), resolving references from pass 1.
  for (const el of styleMapEls) {
    const id = el.getAttribute('id');
    if (!id) continue;
    table.set(id, resolveStyleMap(el, table, resolveHref));
  }

  return table;
}

function collect(el: Element, styles: Element[], styleMaps: Element[]): void {
  for (let child = el.firstElementChild; child; child = child.nextElementSibling) {
    const name = localName(child);
    if (name === 'Style') styles.push(child);
    else if (name === 'StyleMap') styleMaps.push(child);
    collect(child, styles, styleMaps);
  }
}

function resolveStyleMap(
  el: Element,
  table: StyleTable,
  resolveHref: HrefResolver,
): StyleTableEntry {
  let normal: ResolvedStyle = {};
  let highlight: ResolvedStyle | undefined;

  for (const pair of childElements(el, 'Pair')) {
    const key = childText(pair, 'key');
    const style = pairStyle(pair, table, resolveHref);
    if (key === 'highlight') highlight = style;
    else normal = style; // default/normal
  }

  return { normal, highlight };
}

function pairStyle(
  pair: Element,
  table: StyleTable,
  resolveHref: HrefResolver,
): ResolvedStyle {
  // A Pair may reference a shared style by url or contain an inline <Style>.
  const styleUrl = childText(pair, 'styleUrl');
  if (styleUrl) {
    const ref = lookup(table, styleUrl);
    if (ref) return ref.normal;
  }
  const inline = childElements(pair, 'Style')[0];
  return inline ? parseStyleElement(inline, resolveHref) : {};
}

/** Resolve a `#id` (or bare `id`) style reference against the table. */
export function lookup(table: StyleTable, styleUrl: string): StyleTableEntry | undefined {
  const id = styleUrl.replace(/^.*#/, '');
  return table.get(id);
}

/**
 * Compute a placemark's effective style: start from the referenced shared
 * style (styleUrl), then layer any inline <Style> on top.
 */
export function resolvePlacemarkStyle(
  placemark: Element,
  table: StyleTable,
  resolveHref: HrefResolver,
): { style: ResolvedStyle; highlightStyle?: ResolvedStyle } {
  let base: ResolvedStyle = {};
  let highlight: ResolvedStyle | undefined;

  const styleUrl = childText(placemark, 'styleUrl');
  if (styleUrl) {
    const ref = lookup(table, styleUrl);
    if (ref) {
      base = ref.normal;
      highlight = ref.highlight;
    }
  }

  const inline = childElements(placemark, 'Style')[0];
  if (inline) {
    base = mergeStyles(base, parseStyleElement(inline, resolveHref));
  }

  return highlight ? { style: base, highlightStyle: highlight } : { style: base };
}
