/** Tree-walking helpers over the intermediate model. Engine-agnostic. */
import { isContainer, type KmlDocument, type KmlNode } from './types.ts';

/** Depth-first pre-order visit of every node in a document. */
export function visitAll(doc: KmlDocument, fn: (node: KmlNode) => void): void {
  const walk = (nodes: KmlNode[]): void => {
    for (const node of nodes) {
      fn(node);
      if (isContainer(node)) walk(node.children);
    }
  };
  walk(doc.roots);
}

/** All descendant nodes of `node` (excluding itself). */
export function descendants(node: KmlNode): KmlNode[] {
  const out: KmlNode[] = [];
  const walk = (n: KmlNode): void => {
    if (isContainer(n)) {
      for (const child of n.children) {
        out.push(child);
        walk(child);
      }
    }
  };
  walk(node);
  return out;
}

/**
 * The set of "leaf" (renderable) node ids under `node`, inclusive. Placemarks
 * and screen overlays are renderable; containers are not. Used to map a layer
 * tree toggle to the concrete items that must show/hide.
 */
export function renderableIds(node: KmlNode): string[] {
  const out: string[] = [];
  const consider = (n: KmlNode): void => {
    if (n.kind === 'placemark' || n.kind === 'groundOverlay' || n.kind === 'screenOverlay') out.push(n.id);
  };
  consider(node);
  for (const d of descendants(node)) consider(d);
  return out;
}
