import type {
  GroundOverlayNode,
  KmlNode,
  PlacemarkNode,
  Position,
  ScreenOverlayNode,
  Warning,
  WarningKind,
} from '../model/types.ts';
import type { HrefResolver } from './parseStyle.ts';
import { parseKmlColor } from './kmlColor.ts';
import { parsePlacemarkGeometry } from './parseGeometry.ts';
import { resolvePlacemarkStyle, type StyleTable } from './resolveStyles.ts';
import { childBool, childElement, childElements, childNumber, childRawText, childText, localName } from './xml.ts';

/** Mutable state threaded through a parse: id generation, bounds, warnings. */
export interface ParseContext {
  styleTable: StyleTable;
  resolveHref: HrefResolver;
  nodeIndex: Map<string, KmlNode>;
  warnings: Map<WarningKind, Warning>;
  bounds: BoundsAccumulator;
  seq: { n: number };
}

export interface BoundsAccumulator {
  west: number;
  south: number;
  east: number;
  north: number;
  any: boolean;
}

export function newBounds(): BoundsAccumulator {
  return { west: Infinity, south: Infinity, east: -Infinity, north: -Infinity, any: false };
}

function extendBounds(b: BoundsAccumulator, [lon, lat]: Position): void {
  b.any = true;
  if (lon < b.west) b.west = lon;
  if (lon > b.east) b.east = lon;
  if (lat < b.south) b.south = lat;
  if (lat > b.north) b.north = lat;
}

function genId(ctx: ParseContext, el: Element, prefix: string): string {
  const attr = el.getAttribute('id');
  const id = attr && !ctx.nodeIndex.has(attr) ? attr : `${prefix}-${ctx.seq.n++}`;
  return id;
}

function warn(
  ctx: ParseContext,
  kind: WarningKind,
  message: string,
  disposition: Warning['disposition'] = 'skipped',
): void {
  const existing = ctx.warnings.get(kind);
  if (existing) existing.count += 1;
  else ctx.warnings.set(kind, { kind, message, count: 1, disposition });
}

/** Parse the ordered feature children of a container (kml/Document/Folder). */
export function parseChildren(container: Element, ctx: ParseContext): KmlNode[] {
  const out: KmlNode[] = [];
  for (let child = container.firstElementChild; child; child = child.nextElementSibling) {
    const node = parseFeature(child, ctx);
    if (node) out.push(node);
  }
  return out;
}

function parseFeature(el: Element, ctx: ParseContext): KmlNode | null {
  switch (localName(el)) {
    case 'Document':
      return container(el, ctx, 'document');
    case 'Folder':
      return container(el, ctx, 'folder');
    case 'Placemark':
      return placemark(el, ctx);
    case 'GroundOverlay':
      return groundOverlay(el, ctx);
    case 'NetworkLink':
      warn(ctx, 'NetworkLink', 'NetworkLink is not fetched (remote content, CORS).');
      return null;
    case 'ScreenOverlay':
      return screenOverlay(el, ctx);
    case 'PhotoOverlay':
      warn(ctx, 'PhotoOverlay', 'PhotoOverlay is not supported.');
      return null;
    case 'Tour':
      warn(ctx, 'Tour', 'gx:Tour playback is not supported.');
      return null;
    default:
      return null;
  }
}

function readBase(el: Element, ctx: ParseContext, prefix: string) {
  if (childElement(el, 'TimeStamp') || childElement(el, 'TimeSpan')) {
    warn(ctx, 'TimePrimitive', 'TimeStamp/TimeSpan and animated time playback are not supported.');
  }
  return {
    id: genId(ctx, el, prefix),
    name: childText(el, 'name'),
    description: childRawText(el, 'description'),
    visibility: childBool(el, 'visibility') ?? true,
    open: childBool(el, 'open'),
    snippet: childText(el, 'Snippet') ?? childText(el, 'snippet'),
  };
}

function container(el: Element, ctx: ParseContext, kind: 'document' | 'folder'): KmlNode {
  const base = readBase(el, ctx, kind);
  const node = { kind, ...base, children: [] as KmlNode[] } as KmlNode;
  ctx.nodeIndex.set(node.id, node);
  // Parse children after registering, so ids stay stable and ordered.
  (node as { children: KmlNode[] }).children = parseChildren(el, ctx);
  return node;
}

function placemark(el: Element, ctx: ParseContext): PlacemarkNode | null {
  const geometry = parsePlacemarkGeometry(el);
  if (!geometry) {
    if (childElement(el, 'Model')) warn(ctx, 'Model', '3D <Model> geometry is not rendered.');
    if (childElement(el, 'Track') || childElement(el, 'MultiTrack'))
      warn(ctx, 'Track', 'gx:Track is not rendered.');
    return null;
  }

  // Accumulate bounds from every coordinate in the geometry.
  accumulateGeometry(geometry, ctx.bounds);

  const { style, highlightStyle } = resolvePlacemarkStyle(el, ctx.styleTable, ctx.resolveHref);
  const base = readBase(el, ctx, 'placemark');
  const node: PlacemarkNode = {
    kind: 'placemark',
    ...base,
    geometry,
    style,
    highlightStyle,
    extendedData: parseExtendedData(el),
  };
  ctx.nodeIndex.set(node.id, node);
  return node;
}

function accumulateGeometry(
  geometry: { type: string; coordinates?: unknown; geometries?: unknown },
  b: BoundsAccumulator,
): void {
  if (geometry.type === 'Point') {
    extendBounds(b, geometry.coordinates as Position);
  } else if (geometry.type === 'LineString') {
    for (const p of geometry.coordinates as Position[]) extendBounds(b, p);
  } else if (geometry.type === 'Polygon') {
    for (const ring of geometry.coordinates as Position[][])
      for (const p of ring) extendBounds(b, p);
  } else if (geometry.type === 'MultiGeometry') {
    for (const g of geometry.geometries as { type: string }[])
      accumulateGeometry(g as never, b);
  }
}

function groundOverlay(el: Element, ctx: ParseContext): GroundOverlayNode | null {
  const box = childElement(el, 'LatLonBox');
  const icon = childElement(el, 'Icon');
  const rawHref = icon ? childText(icon, 'href') : undefined;
  if (!box || !rawHref) {
    warn(ctx, 'ParseError', 'GroundOverlay without LatLonBox/Icon skipped.');
    return null;
  }

  const north = childNumber(box, 'north');
  const south = childNumber(box, 'south');
  const east = childNumber(box, 'east');
  const west = childNumber(box, 'west');
  if (north == null || south == null || east == null || west == null) return null;

  const base = readBase(el, ctx, 'overlay');
  const node: GroundOverlayNode = {
    kind: 'groundOverlay',
    ...base,
    iconHref: ctx.resolveHref(rawHref),
    latLonBox: { north, south, east, west, rotation: childNumber(box, 'rotation') ?? 0 },
    drawOrder: childNumber(el, 'drawOrder'),
    color: parseKmlColor(childText(el, 'color')),
  };
  if (node.latLonBox.rotation !== 0) {
    warn(
      ctx,
      'ParseError',
      'GroundOverlay rotation is approximated on the 2D map.',
      'approximated',
    );
  }
  ctx.bounds.any = true;
  ctx.bounds.west = Math.min(ctx.bounds.west, west);
  ctx.bounds.east = Math.max(ctx.bounds.east, east);
  ctx.bounds.south = Math.min(ctx.bounds.south, south);
  ctx.bounds.north = Math.max(ctx.bounds.north, north);
  ctx.nodeIndex.set(node.id, node);
  return node;
}

function screenOverlay(el: Element, ctx: ParseContext): ScreenOverlayNode | null {
  const icon = childElement(el, 'Icon');
  const rawHref = icon ? childText(icon, 'href') : undefined;
  if (!rawHref) {
    warn(ctx, 'ScreenOverlay', 'ScreenOverlay without an Icon href skipped.');
    return null;
  }

  const base = readBase(el, ctx, 'screen-overlay');
  const node: ScreenOverlayNode = {
    kind: 'screenOverlay',
    ...base,
    iconHref: ctx.resolveHref(rawHref),
    screenXY: parseOverlayPoint(childElement(el, 'screenXY')),
    overlayXY: parseOverlayPoint(childElement(el, 'overlayXY')),
    drawOrder: childNumber(el, 'drawOrder'),
  };
  ctx.nodeIndex.set(node.id, node);
  return node;
}

function parseOverlayPoint(el: Element | null): ScreenOverlayNode['screenXY'] {
  const x = Number(el?.getAttribute('x') ?? 0);
  const y = Number(el?.getAttribute('y') ?? 0);
  return {
    x: Number.isFinite(x) ? x : 0,
    y: Number.isFinite(y) ? y : 0,
    xUnits: overlayUnit(el, 'xunits'),
    yUnits: overlayUnit(el, 'yunits'),
  };
}

function overlayUnit(el: Element | null, attr: string): ScreenOverlayNode['screenXY']['xUnits'] {
  const value = el?.getAttribute(attr) ?? el?.getAttribute(attr.replace('units', 'Units'));
  return value === 'pixels' || value === 'insetPixels' ? value : 'fraction';
}

function parseExtendedData(el: Element): Record<string, string> | undefined {
  const ext = childElement(el, 'ExtendedData');
  if (!ext) return undefined;
  const out: Record<string, string> = {};
  for (const data of childElements(ext, 'Data')) {
    const name = data.getAttribute('name');
    if (!name) continue;
    out[name] = childText(data, 'value') ?? childText(data, 'displayName') ?? '';
  }
  // SimpleData inside SchemaData.
  for (const schema of childElements(ext, 'SchemaData')) {
    for (const sd of childElements(schema, 'SimpleData')) {
      const name = sd.getAttribute('name');
      if (name) out[name] = (sd.textContent ?? '').trim();
    }
  }
  return Object.keys(out).length ? out : undefined;
}
