import { SaxesParser, type SaxesTagNS } from 'saxes';

/**
 * Minimal Element-shaped node used by the worker parser. It implements only
 * the DOM surface consumed by our KML parser, avoiding a browser DOM and its
 * main-thread-only DOMParser dependency.
 */
class StreamElement {
  readonly children: StreamElement[] = [];
  readonly content: Array<string | StreamElement> = [];
  nextElementSibling: StreamElement | null = null;

  constructor(
    readonly nodeName: string,
    readonly localName: string,
    private readonly attributes: Map<string, string>,
  ) {}

  get firstElementChild(): StreamElement | null {
    return this.children[0] ?? null;
  }

  get textContent(): string {
    return this.content.map((part) => typeof part === 'string' ? part : part.textContent).join('');
  }

  getAttribute(name: string): string | null {
    return this.attributes.get(name) ?? null;
  }

  appendChild(child: StreamElement): void {
    const previous = this.children[this.children.length - 1];
    if (previous) previous.nextElementSibling = child;
    this.children.push(child);
    this.content.push(child);
  }

  appendText(text: string): void {
    if (text) this.content.push(text);
  }
}

/** Parse XML into the lightweight Element-compatible tree used in workers. */
export function parseStreamingXml(xml: string): Element {
  let root: StreamElement | null = null;
  let parseError: Error | null = null;
  const stack: StreamElement[] = [];
  const parser = new SaxesParser({ xmlns: true });

  parser.on('opentag', (tag: SaxesTagNS) => {
    const attributes = new Map<string, string>();
    for (const attribute of Object.values(tag.attributes)) {
      attributes.set(attribute.name, attribute.value);
      // KML attributes are normally unqualified. Local lookup is useful for
      // namespace-aware archives that qualify otherwise ordinary attributes.
      if (!attributes.has(attribute.local)) attributes.set(attribute.local, attribute.value);
    }
    const element = new StreamElement(tag.name, tag.local, attributes);
    const parent = stack[stack.length - 1];
    if (parent) parent.appendChild(element);
    else root = element;
    stack.push(element);
  });
  const appendText = (text: string): void => stack[stack.length - 1]?.appendText(text);
  parser.on('text', appendText);
  parser.on('cdata', appendText);
  parser.on('closetag', () => { stack.pop(); });
  parser.on('error', (error) => { parseError = error; });
  parser.write(xml).close();

  const error = parseError as Error | null;
  if (error) throw new Error(`Invalid KML/XML: ${error.message}`);
  if (!root) throw new Error('No <kml> root element found.');
  return root as unknown as Element;
}
