import type { Rgba } from '../model/types.ts';

/**
 * KML colours are hex strings in `aabbggrr` order (alpha, blue, green, red) —
 * the reverse of the familiar CSS `#rrggbbaa`. Convert to an {r,g,b,a} value
 * with channels 0–255 and alpha normalized to 0–1.
 */
export function parseKmlColor(text: string | null | undefined): Rgba | undefined {
  if (!text) return undefined;
  const hex = text.trim().replace(/^#/, '');
  if (!/^[0-9a-fA-F]{8}$/.test(hex)) {
    // Some files use rrggbb (no alpha) — treat as opaque.
    if (/^[0-9a-fA-F]{6}$/.test(hex)) {
      return {
        r: parseInt(hex.slice(0, 2), 16),
        g: parseInt(hex.slice(2, 4), 16),
        b: parseInt(hex.slice(4, 6), 16),
        a: 1,
      };
    }
    return undefined;
  }
  const a = parseInt(hex.slice(0, 2), 16);
  const b = parseInt(hex.slice(2, 4), 16);
  const g = parseInt(hex.slice(4, 6), 16);
  const r = parseInt(hex.slice(6, 8), 16);
  return { r, g, b, a: a / 255 };
}

/** Serialize an Rgba to a CSS `rgba(...)` string for rendering. */
export function rgbaToCss(c: Rgba): string {
  return `rgba(${c.r}, ${c.g}, ${c.b}, ${round(c.a)})`;
}

function round(n: number): number {
  return Math.round(n * 1000) / 1000;
}

export const WHITE: Rgba = { r: 255, g: 255, b: 255, a: 1 };
