/// <reference lib="webworker" />
import { collectStatistics } from '../model/statistics.ts';
import type { KmlDocument } from '../model/types.ts';
import { unzipKmz } from '../loaders/unzipKmz.ts';
import { parseKmlStreaming } from '../parser/parseKml.ts';
import { documentToGeoJSON } from '../render/maplibre/toGeoJSON.ts';
import type { KmlWorkerRequest, KmlWorkerResponse } from './protocol.ts';

const scope = self as DedicatedWorkerGlobalScope;
const cancelled = new Set<number>();
const RENDER_BATCH_SIZE = 5_000;

scope.onmessage = (event: MessageEvent<KmlWorkerRequest>) => {
  const message = event.data;
  if (message.type === 'cancel') {
    cancelled.add(message.taskId);
    post({ type: 'cancel', taskId: message.taskId });
    return;
  }
  void load(message.taskId, message.fileName, new Uint8Array(message.bytes));
};

async function load(taskId: number, fileName: string, bytes: Uint8Array): Promise<void> {
  const started = Date.now();
  try {
    let text: string;
    let assets = new Map<string, Uint8Array>();
    let expandedBytes = bytes.byteLength;
    if (isZip(bytes)) {
      post({ type: 'progress', taskId, phase: 'unzip', message: 'Expanding KMZ archive…' });
      const archive = await unzipKmz(bytes);
      checkCancelled(taskId);
      text = archive.rootKml;
      expandedBytes = [...archive.entries.values()].reduce((sum, entry) => sum + entry.byteLength, 0);
      assets = archive.entries;
    } else {
      text = new TextDecoder('utf-8').decode(bytes);
    }

    post({ type: 'progress', taskId, phase: 'parse', message: `Parsing ${fileName}…` });
    const document = parseKmlStreaming(text);
    checkCancelled(taskId);
    document.statistics = collectStatistics(document, bytes.byteLength, expandedBytes, Date.now() - started);
    assets = referencedAssets(document, assets);
    post({
      type: 'metadata',
      taskId,
      featureCount: document.statistics.featureCount,
      coordinateCount: document.statistics.coordinateCount,
    });
    post({ type: 'progress', taskId, phase: 'index', message: 'Preparing map indexes…' });
    const renderData = documentToGeoJSON(document);
    for (const geometry of ['points', 'lines', 'polygons'] as const) {
      const features = renderData[geometry].features;
      if (features.length === 0) {
        post({ type: 'renderBatch', taskId, geometry, count: 0, features: [] });
        continue;
      }
      for (let offset = 0; offset < features.length; offset += RENDER_BATCH_SIZE) {
        checkCancelled(taskId);
        const batch = features.slice(offset, offset + RENDER_BATCH_SIZE);
        post({ type: 'renderBatch', taskId, geometry, count: Math.min(features.length, offset + batch.length), features: batch });
      }
    }
    checkCancelled(taskId);
    const transfer = [...assets.values()].map((entry) => entry.buffer as ArrayBuffer);
    const response: KmlWorkerResponse = { type: 'complete', taskId, document, assets };
    scope.postMessage(response, transfer);
  } catch (error) {
    if ((error as Error).name === 'AbortError') {
      post({ type: 'cancel', taskId });
    } else {
      post({ type: 'error', taskId, name: (error as Error).name, message: (error as Error).message });
    }
  } finally {
    cancelled.delete(taskId);
  }
}

function referencedAssets(document: KmlDocument, entries: Map<string, Uint8Array>): Map<string, Uint8Array> {
  if (entries.size === 0) return entries;
  const hrefs = new Set<string>();
  for (const node of document.nodeIndex.values()) {
    if (node.kind === 'placemark') {
      if (node.style.icon?.href) hrefs.add(normalize(node.style.icon.href));
      if (node.highlightStyle?.icon?.href) hrefs.add(normalize(node.highlightStyle.icon.href));
    } else if (node.kind === 'groundOverlay' || node.kind === 'screenOverlay') {
      hrefs.add(normalize(node.iconHref));
    }
  }
  const result = new Map<string, Uint8Array>();
  for (const href of hrefs) {
    const direct = entries.get(href);
    if (direct) {
      result.set(href, direct);
      continue;
    }
    const base = href.split('/').pop();
    if (!base) continue;
    const loose = [...entries].find(([path]) => path.split('/').pop() === base);
    if (loose) result.set(loose[0], loose[1]);
  }
  return result;
}

function normalize(path: string): string {
  return path.replace(/\\/g, '/').replace(/^\.\//, '');
}

function checkCancelled(taskId: number): void {
  if (!cancelled.has(taskId)) return;
  const error = new Error('Load cancelled.');
  error.name = 'AbortError';
  throw error;
}

function post(message: KmlWorkerResponse): void {
  scope.postMessage(message);
}

function isZip(bytes: Uint8Array): boolean {
  return bytes[0] === 0x50 && bytes[1] === 0x4b && bytes[2] === 0x03 && bytes[3] === 0x04;
}
