import type { DocumentStatistics, Geometry, KmlDocument } from './types.ts';

export const MAX_RENDERABLE_FEATURES = 100_000;
export const MAX_RENDER_COORDINATES = 2_000_000;
export const LARGE_POINT_THRESHOLD = 20_000;

export function collectStatistics(
  doc: KmlDocument,
  sourceBytes = 0,
  expandedBytes = sourceBytes,
  parseDurationMs = 0,
): DocumentStatistics {
  const statistics: DocumentStatistics = {
    featureCount: 0,
    coordinateCount: 0,
    geometry: { points: 0, lines: 0, polygons: 0, overlays: 0 },
    sourceBytes,
    expandedBytes,
    parseDurationMs,
    simplified: false,
  };
  for (const node of doc.nodeIndex.values()) {
    if (node.kind === 'placemark') {
      statistics.featureCount += 1;
      countGeometry(node.geometry, statistics);
    } else if (node.kind === 'groundOverlay') {
      statistics.featureCount += 1;
      statistics.geometry.overlays += 1;
    }
  }
  statistics.simplified = statistics.coordinateCount > MAX_RENDER_COORDINATES;
  return statistics;
}

function countGeometry(geometry: Geometry, statistics: DocumentStatistics): void {
  switch (geometry.type) {
    case 'Point':
      statistics.geometry.points += 1;
      statistics.coordinateCount += 1;
      break;
    case 'LineString':
      statistics.geometry.lines += 1;
      statistics.coordinateCount += geometry.coordinates.length;
      break;
    case 'Polygon':
      statistics.geometry.polygons += 1;
      for (const ring of geometry.coordinates) statistics.coordinateCount += ring.length;
      break;
    case 'MultiGeometry':
      for (const child of geometry.geometries) countGeometry(child, statistics);
      break;
  }
}
