/**
 * Thin helpers over the DOM for reading KML. KML documents sometimes carry a
 * default namespace, so we match on local names rather than qualified names to
 * stay robust across `http://www.opengis.net/kml/2.2`, the older Google
 * namespace, and the `gx:` extension namespace.
 */

/** Direct child elements of `el` whose local name is `name`. */
export function childElements(el: Element, name: string): Element[] {
  const out: Element[] = [];
  for (let child = el.firstElementChild; child; child = child.nextElementSibling) {
    if (localName(child) === name) out.push(child);
  }
  return out;
}

/** First direct child element with the given local name, or null. */
export function childElement(el: Element, name: string): Element | null {
  for (let child = el.firstElementChild; child; child = child.nextElementSibling) {
    if (localName(child) === name) return child;
  }
  return null;
}

/** Trimmed text of the first direct child element with `name`, or undefined. */
export function childText(el: Element, name: string): string | undefined {
  const child = childElement(el, name);
  const text = child?.textContent;
  return text == null ? undefined : text.trim();
}

/** Raw (untrimmed) inner text of the first direct child element with `name`. */
export function childRawText(el: Element, name: string): string | undefined {
  const child = childElement(el, name);
  return child?.textContent ?? undefined;
}

export function childNumber(el: Element, name: string): number | undefined {
  const text = childText(el, name);
  if (text == null || text === '') return undefined;
  const n = Number(text);
  return Number.isFinite(n) ? n : undefined;
}

/** Parse a KML boolean (`1`/`0`, `true`/`false`). */
export function childBool(el: Element, name: string): boolean | undefined {
  const text = childText(el, name)?.toLowerCase();
  if (text == null) return undefined;
  return text === '1' || text === 'true';
}

/** The local (namespace-stripped) name of an element, lowercased-insensitive. */
export function localName(el: Element): string {
  return el.localName || el.nodeName.replace(/^.*:/, '');
}
